import {TILE,legalMoves,fallingObjects,immovable,fuseLimit} from './dungeon-board.js';
// The zeroed charge field is retained only to read older saves and recorded replays.
export const newMechanics=(board=[])=>({player:{charge:0,cripple:-1},enemy:{charge:0,cripple:-1},devices:[],pending:null,turrets:[],falling:fallingObjects(board)});
export function validateMechanics(m,board,legacy=false){const side=x=>x&&Number.isInteger(x.charge)&&x.charge>=0&&x.charge<=2&&Number.isInteger(x.cripple)&&x.cripple>=-1&&x.cripple<=5;return (m?.devices===undefined&&!board.some(n=>n===14||n===15)||Array.isArray(m.devices)&&m.devices.length<=64&&new Set(m.devices.map(d=>d.cell)).size===m.devices.length&&m.devices.every(d=>d&&Number.isInteger(d.cell)&&d.cell>=0&&d.cell<64&&[14,15].includes(d.type)&&board[d.cell]===d.type&&['player','enemy'].includes(d.owner)&&Number.isInteger(d.fallen)&&d.fallen>=0&&d.fallen<(d.type===15?4:8)&&Number.isInteger(d.channel)&&d.channel>=-1&&d.channel<5)&&board.filter(t=>t===14||t===15).length===m.devices.length)&&(m?.pending==null||['player','enemy'].includes(m.pending.actor)&&typeof m.pending.extra==='boolean'&&(m.pending.patchActive===undefined||typeof m.pending.patchActive==='boolean')&&Number.isInteger(m.pending.kits)&&m.pending.kits>=0&&m.pending.kits<=6400&&m.pending.finish&&Array.isArray(m.pending.finish.sources)&&m.pending.finish.sources.length<=8&&m.pending.finish.sources.every(x=>x&&typeof x.label==='string'&&x.label.length<=160&&Number.isFinite(x.raw)&&x.raw>=0)&&(m.pending.finish.selfCripple===undefined||Number.isInteger(m.pending.finish.selfCripple)&&m.pending.finish.selfCripple>=0&&m.pending.finish.selfCripple<=5)&&Number.isFinite(m.pending.finish.actualDamage)&&typeof m.pending.finish.crit==='boolean')&&Array.isArray(board)&&m&&side(m.player)&&side(m.enemy)&&Array.isArray(m.falling)&&m.falling.length<=64&&new Set(m.falling.map(o=>o?.cell)).size===m.falling.length&&m.falling.every(o=>o&&Number.isInteger(o.cell)&&o.cell>=0&&o.cell<64&&[7,11].includes(o.type)&&board[o.cell]===o.type&&Number.isInteger(o.fallen)&&o.fallen>=0&&o.fallen<fuseLimit(o.type)&&(o.type!==11||[20,30,45].includes(o.power)&&typeof o.minefield==='boolean'&&(o.owner===undefined||['player','enemy'].includes(o.owner))))&&board.filter(n=>n===7||n===11).length===m.falling.length&&Array.isArray(m.turrets)&&m.turrets.length<=64&&new Set(m.turrets.map(t=>t?.cell)).size===m.turrets.length&&m.turrets.every(t=>t&&Number.isInteger(t.cell)&&t.cell>=0&&t.cell<64&&['player','enemy'].includes(t.owner)&&Number.isInteger(t.originRow)&&t.originRow>=0&&t.originRow<8&&Number.isInteger(t.fallen)&&t.fallen>=0&&t.fallen<(legacy?3:2)&&board[t.cell]===TILE.TURRET)&&board.filter(n=>n===TILE.TURRET).length===m.turrets.length;}
export const canMove=(b,actor,a,c)=>!immovable(b.board[a])&&!immovable(b.board[c])&&(b.mechanics[actor].cripple<0||b.board[a]!==b.mechanics[actor].cripple&&b.board[c]!==b.mechanics[actor].cripple);
export const combatMoves=(b,actor)=>legalMoves(b.board).filter(([a,c])=>canMove(b,actor,a,c));
export const boardOptions=(b,actor)=>({specials:true,actor,devices:b.mechanics.devices,turrets:b.mechanics.turrets,falling:b.mechanics.falling});
export function finishMechanics(b,actor,result,random){
 b.mechanics[actor].cripple=-1;
 // A crit raises the chance to 30%; it does not guarantee a disable or penalize its attacker.
 if(result.selfCripple!==undefined)b.mechanics[actor].cripple=result.selfCripple;
 const chance=result.actualDamage>0?(result.crit?.30:result.sources.some(x=>x.label.startsWith('Strike'))?.15:0):0;
 if(chance&&random()<chance){const target=actor==='player'?'enemy':'player',type=Math.floor(random()*6);b.mechanics[target].cripple=type;result.crippled={actor:target,type,chance};}
}
